@:from public static function fromString(str:String):AssetSource
	{
		return switch (StringTools.trim(str).toLowerCase())
		{
			case "source": SOURCE;
			case "mods": MODS;
			case "both": BOTH;
			default: MODS;
		}
	}

@:to public inline function toString():String
	{
		return switch (this)
		{
			case SOURCE: "source";
			case MODS: "mods";
			case BOTH: "both";
			default: "mods";
		}
	}
